sql_query:
SELECT DISTINCT gene_name
FROM varInfo_synthetic
WHERE HighImpact = 1 AND (ALS_1 = 2 OR ALS_2 = 2 OR ALS_3 = 2 OR ALS_4 = 2 OR ALS_5 = 2);

SELECT DISTINCT var_id 
FROM varInfo_synthetic 
WHERE HighImpact = 'YES' AND (ALS_1 = 2 OR ALS_2 = 2 OR ALS_3 = 2 OR ALS_4 = 2 OR ALS_5 = 2);

SELECT SUM(CASE WHEN VAR_id IN (SELECT VAR_id FROM varInfo_synthetic WHERE gene_name = 'ALS' AND (HighImpact OR ModerateImpact)) THEN 1 ELSE 0 END) AS TotalEffectAllelesInALSCases,
       SUM(CASE WHEN VAR_id NOT IN (SELECT VAR_id FROM varInfo_synthetic WHERE gene_name = 'ALS' AND (HighImpact OR ModerateImpact)) THEN 1 ELSE 0 END) AS TotalEffectAllelesInControls
FROM varInfo_synthetic;

SELECT 
    SUM(CASE WHEN CHROM = 'ALS' THEN 1 ELSE 0 END) - 
    SUM(CASE WHEN CHROM = 'Control' THEN 1 ELSE 0 END) AS total_burden;

SELECT CHROM, POS, ID, REF, ALT, QUAL, FILTER, AC, AN, AF, gene_name, HighImpact, ModerateImpact, Synonymous, CADDphred, PolyPhen, SIFT, ALS_1, ALS_2, ALS_3, ALS_4, ALS_5, Control_1, Control_2, Control_3, Control_4, Control_5
FROM varInfo_synthetic
WHERE AC > 0;

SELECT VAR_id, CHROM, POS, ID, REF, ALT, QUAL, FILTER, AC, AN, AF, gene_name, HighImpact, ModerateImpact, Synonymous, CADDphred, PolyPhen, SIFT
FROM varInfo_synthetic
ORDER BY HighImpact DESC, ModerateImpact DESC, Synonymous ASC, CADDphred DESC, PolyPhen DESC, SIFT DESC;

SELECT COUNT(*) 
FROM varInfo_synthetic 
WHERE gene_name = 'SOD1' AND HighImpact = 'Pathogenic';
